import java.net.URL;
import java.nio.file.Path;

/** Finite installed-image ownership check; this fixture is never packaged in the SDK. */
public final class LinkedM3SdkOwnership {
    private LinkedM3SdkOwnership() { }

    private static void owner(String name, String module, boolean bootstrap) throws Exception {
        Class<?> type = Class.forName(name, false, ClassLoader.getSystemClassLoader());
        if (!type.getModule().isNamed() || !module.equals(type.getModule().getName())) {
            throw new AssertionError(name + " module=" + type.getModule());
        }
        if (bootstrap && type.getClassLoader() != null) {
            throw new AssertionError(name + " is not bootstrap-owned");
        }
        String resource = "/" + name.replace('.', '/') + ".class";
        URL location = type.getResource(resource);
        if (location == null || !"jrt".equals(location.getProtocol())
                || !location.getPath().equals("/" + module + resource)) {
            throw new AssertionError(name + " resource=" + location);
        }
        if (ModuleLayer.boot().findModule(module).orElseThrow() != type.getModule()) {
            throw new AssertionError(name + " is not in the installed boot layer");
        }
        System.out.println("OWNER " + name + " " + location);
    }

    public static void main(String[] arguments) throws Exception {
        Path expected = Path.of(arguments[0]).toRealPath();
        Path actual = Path.of(System.getProperty("java.home")).toRealPath();
        if (!actual.equals(expected)) {
            throw new AssertionError("java.home=" + actual + " expected=" + expected);
        }
        owner("java.lang.String", "java.base", true);
        owner("java.lang.M3String", "java.base", true);
        owner("java.util.CollectionViews", "java.base", true);
        owner("com.m3.collections.M3CollectionViews", "com.m3.collections", false);
        owner("com.m3.collections.M3IndexedListSnapshot", "com.m3.collections", false);
        owner("com.m3.collections.M3IndexMaskCompactor", "com.m3.collections", false);
        owner("com.m3.collections.M3SignalOrder", "com.m3.collections", false);
        System.out.println("PASS installed M3JDK21 ownership: 7 classes from the linked jrt image");
    }
}

