import java.lang.invoke.MethodHandle;
import java.lang.invoke.MethodHandles;
import java.lang.invoke.MethodType;
import java.lang.invoke.StringConcatFactory;
import java.lang.reflect.Field;

public final class M3StringNullableConcatProbe {
    private static int checks;

    private M3StringNullableConcatProbe() {}

    public static void main(String[] args) throws Throwable {
        same(single(null), "left-long-null-right-long", "typed String null");
        same(single(""), "left-long--right-long", "typed String empty");
        same(single("v"), "left-long-v-right-long", "typed String value");
        same(triple(null, "b", "c"), "null|b|c", "first null");
        same(triple("a", null, "c"), "a|null|c", "middle null");
        same(triple("a", "b", null), "a|b|null", "last null");
        same(triple(null, null, null), "null|null|null", "all null");
        same(mixed(null, 3, '\u03bb'), "null|3|\u03bb", "String and primitive");

        StringBuilder trace = new StringBuilder();
        same(threePieces(trace), "null|b|null", "side-effect content");
        same(trace.toString(), "ABC", "left-to-right evaluation");

        int[] calls = {0};
        Object nullText = new Object() {
            @Override public String toString() {
                calls[0]++;
                return null;
            }
        };
        same(object(nullText), "left-long-null-right-long", "null toString");
        check(calls[0] == 1, "one toString call");

        MethodHandle target = StringConcatFactory.makeConcatWithConstants(
                MethodHandles.lookup(), "makeConcatWithConstants",
                MethodType.methodType(String.class, String.class, String.class),
                "left-long-\u0001|\u0001-right-long").dynamicInvoker();
        same((String) target.invokeExact((String) null, "x"),
                "left-long-null|x-right-long", "explicit bootstrap first null");
        same((String) target.invokeExact("x", (String) null),
                "left-long-x|null-right-long", "explicit bootstrap last null");
        same((String) target.invokeExact((String) null, (String) null),
                "left-long-null|null-right-long", "explicit bootstrap all null");

        String first = single(null);
        String second = single(null);
        check(first != second, "fresh concat wrapper");
        if (args.length != 0) {
            Field m3 = String.class.getDeclaredField("m3");
            m3.setAccessible(true);
            if (args[0].equals("admitted")) {
                check(m3.get(first) != null, "M3 composition admitted");
            } else if (args[0].equals("refused")) {
                check(m3.get(first) == null, "zero-budget flat fallback");
            } else {
                throw new IllegalArgumentException(args[0]);
            }
        }
        System.out.println("M3_STRING_NULLABLE_CONCAT_PROBE_PASS|checks=" + checks);
    }

    private static String single(String value) {
        return "left-long-" + value + "-right-long";
    }

    private static String triple(String a, String b, String c) {
        return a + "|" + b + "|" + c;
    }

    private static String mixed(String a, int b, char c) {
        return a + "|" + b + "|" + c;
    }

    private static String object(Object value) {
        return "left-long-" + value + "-right-long";
    }

    private static String threePieces(StringBuilder trace) {
        return piece(trace, "A", null) + "|"
                + piece(trace, "B", "b") + "|" + piece(trace, "C", null);
    }

    private static String piece(StringBuilder trace, String label, String value) {
        trace.append(label);
        return value;
    }

    private static void same(String actual, String expected, String label) {
        check(actual.equals(expected), label + ": expected=" + expected + " actual=" + actual);
    }

    private static void check(boolean ok, String label) {
        checks++;
        if (!ok) throw new AssertionError(label);
    }
}
